\label{assumpm}(Compact setting)	Assume that 
	\begin{itemize}
		\item $M$ is a $(d+c)$-dimensional compact closed not necessarily orientable smooth manifold, with $d,c\in\mathbb{Z}_{\ge 1},$
		\item $[\Sigma]\in H_d(M,\mathbb{Z})$ is a $d$-dimensional integral homology class,
		\item $g$ is a smooth Riemannian metric on $M.$
\end{itemize}

\label{defntm}
Use $G_d(M,\mathbb{Z})$ to denote the torsion subgroup of $H_d(M,\mathbb{Z})$, i.e., 
\begin{align*}
G_d(M,\mathbb{Z})=\bigoplus_{i\in I}\mathbb{Z}/p_i^{\nu_i}\mathbb{Z}.
\end{align*}Define the $d$-th torsion number $\tau_d$ of $M$ to be
\begin{align*}
\tau_d=\operatorname{lcm}_{i\in I}p_i^{\nu_i},
\end{align*}where $\operatorname{lcm}$ means the 
least common multiple. Set $\tau_d=1$ if $H_d(M,\mathbb{Z})$ is torsion-free.

We classify the integral homology class $[\Sigma]$ according to its algebraic properties.\label{defnhom}
\begin{itemize}
\item 	We say $[\Sigma]$ is a torsion class if there is an integer $v$ such that $v[\Sigma]=0,$ i.e., belonging to $G_d(M,\mathbb{Z})$. Otherwise we say $[\Sigma]$ is a non-torsion class,
\item If $[\Sigma]$ is a non-torsion class, $M$ is orientable, and $d\ge1 ,c\ge 2$, then the representable multiplicity $\mu_{[\Sigma]}$ of $[\Sigma]$ is defined to be the smallest integer $\mu_{[\Sigma]}\in\mathbb{Z}_{\ge 2}$ such that $\mu_{[\Sigma]}[\Sigma]$ can be represented by a smoothly embedded connected submanifold.
\end{itemize}

\label{defni}
	The $R$-reduction $[\Sigma]^R$ of the integral homology class $[\Sigma]$ is defined to be
	\begin{align*}
		[\Sigma]^R=\iota([\Sigma]\otimes 1)\in H_d(M,R),
	\end{align*}where $\iota$ is the natural injection in (\ref{equct}) and $1$ is the unit element in $R.$

\label{defnnm}
		We say a map $\left\lVert\cdot \right\rVert^R:R\to \mathbb{R}_{\ge0}$ is a norm on $R$ if $\left\lVert\cdot\right\rVert^R$ satisfies the following three properties:
		\begin{itemize}
			\item (reversibility) for all $e\in R$, we have
			\begin{align*}
				\left\lVert-e\right\rVert^R=\left\lVerte\right\rVert^R,
			\end{align*}
			\item (triangle inequality) for all $e,f\in R$, we have
			\begin{align*}
				\left\lVerte+f\right\rVert^R\le \left\lVerte\right\rVert^R+\left\lVertf\right\rVert^R.
			\end{align*}
			\item (positivity) we have the equivalence of propositions, for all $e\in R,$
			\begin{align*}
				\left\lVerte\right\rVert^R=0\Leftrightarrow e=0. 
			\end{align*} 
		\end{itemize}

When the canonical homomorphism $\mathbb{Z}\to R$ is norm non-increasing, define the $R$-reduction $T^R$ of an integral current $T\in[\Sigma]$ to be
		\begin{align*}
			T^R=\iota(T\otimes 1)\in [\Sigma]^R.
		\end{align*}

\label{defnrarea}
		Define the $R$-area $\left\lVert[\Sigma]\right\rVert^R_g$ of $[\Sigma]^R$ to be
		\begin{align}\label{defnra}
			\left\lVert[\Sigma]\right\rVert^R_g=\inf_{\substack{T\in\mathcal{F}_g(M,R)\\ T\in[\Sigma]^R}}\mathbf{M}_g^R(T).
		\end{align}
		We say an $R$-flat chain $T\in[\Sigma]^R$ is $R$-area-minimizing in $[\Sigma]^R$ with respect to metric $g,$ if $T$ achieves the $R$-area of $[\Sigma]^R$ defined in (\ref{defnra}), i.e.,
		\begin{align*}
			\mathbf{M}^R_g(T)=\left\lVert[\Sigma]\right\rVert^R_g.
		\end{align*}

The following inequality holds
		\begin{align}\label{eqnormcomp}
			\left\lVert[\Sigma]\right\rVert^R_g\le \inf_{T\in[\Sigma]}\mathbf{M}_g^{R}(T^R).
		\end{align}

\label{defnnorm}Define
		\begin{align*}
			\left\lVert\cdot\right\rVert^{\mathbb{Z}}=&|\cdot|,\\
			\left\lVert\cdot\right\rVert^{\mathbb{R}}=&|\cdot|,\\
			\left\lVert\cdot\right\rVert^{\mathbb{Z}/n\mathbb{Z}}=&|\cdot|_{(-\frac{n}{2},\frac{n}{2}]}.
		\end{align*}

\label{fctncmp}The following inequality always holds
		\begin{align}\label{eqinnorm}
			\left\lVert[\Sigma]\right\rVert^R_g\le \left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_g.
		\end{align}

For a subset $S\subset H_d(M,\mathbb{Z}),$		define the set of $R$-area-minimizing representatives $\mathbf{MIN}_g^R\left(S\right)$ of $S^R$ to be
		\begin{align*}
			\mathbf{MIN}_g^R\left(S\right)=\{T|T\in \mathcal{F}_g(M,R),[T]\in S^R,\mathbf{M}^R_g(T)=\inf_{[\Gamma]\in S^R}\left\lVert[\Gamma]\right\rVert^R_g\}.
		\end{align*}

\label{thmv}
		For all $[\Sigma]\in H_d(M,\mathbb{Z})$, there exists a positive integer $N_{[\Sigma],g}$, and an open set $\Omega_{[\Sigma],g}$ containing $g$ in the space of Riemannian metrics, both depending only on $[\Sigma]$ and $g$, such that for all metrics $h\in\Omega_{[\Sigma],g},$ all $n\ge N_{[\Sigma],g},$ with $\tau_d|n$    
		\begin{itemize}
			\item equality holds in (\ref{eqinnorm}), i.e., $			\left\lVert[\Sigma]\right\rVert_h^{\mathbb{Z}/n\mathbb{Z}}=\left\lVert[\Sigma]\right\rVert_h^\mathbb{Z},$
			\item the $\mathbb{Z}/n\mathbb{Z}$-reduction restricted to $\mathbf{MIN}_h^{\mathbb{Z}}\left([\Sigma]\right)$ is a one to one map from  		$\mathbf{MIN}_h^{\mathbb{Z}}\left([\Sigma]\right)$ to $\mathbf{MIN}_h^{\mathbb{Z}/n\mathbb{Z}}\left([\Sigma]\right)$.	
		\end{itemize}

\label{thmvn}
		If $d\ge 1,c\ge 2,$ $M$ is orientable, and $[\Sigma]$ a non-torsion class, then for any real number $\rho>1$ and all integers $n\ge 2$ with $\operatorname{gcd}\left(n,\mu_{[\Sigma]}\right)=1,$  there exists a non-empty open set $\Omega'_{[\Sigma],n,\rho}$ in the space of Riemannian metrics, depending on $[\Sigma],n,$ and $\rho,$ such that for all metrics $h\in\Omega'_{[\Sigma],n,\rho}$ we have
		\begin{align}
			\label{eqzv}	{\left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_h}>& \rho{\left\lVert[\Sigma]\right\rVert^{\mathbb{Z}/n\mathbb{Z}}_h},\\
			\label{eqzr}	{\left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_h}>&\rho{\left\lVert[\Sigma]\right\rVert^{\mathbb{R}}_h},\\
			\label{eqzz}	{\left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_h}>& \rho{\left\lVert\mu_{[\Sigma]}[\Sigma]\right\rVert^{\mathbb{Z}}_h}.
		\end{align}

\label{assumpmb}	Assume that $c,d\in\mathbb{Z}_{\ge1}$ and
	\begin{enumerate}
	\item $W$ is either a $(d-1)$-dimensional compact smooth submanifold or a   compact $(d-1)$-dimensional subanalytic set of $M=\mathbb{R}^{d+c}$,\label{assumpmbr}
	\item $[\Sigma]\in H_d(\mathbb{R}^{d+c},W,\mathbb{Z})$ is a $d$-dimensional relative integral homology class with $d\ge 2$.
	\end{enumerate}

\label{defntsw}
Assume $d\ge 2$. For $d$-dimensional $R$-flat chains $T$ with $\partial T$ supported in $W,$ we define
\begin{align*}
	[T]=\partial^{-1}[\partial T]\in H_d(\mathbb{R}^{d+c},W,R). 
\end{align*}

\label{defnrareab}
	For $d\ge 2,c\ge1$ define the $R$-area $\left\lVert[\Sigma]\right\rVert^R_\delta$ of $[\Sigma]^R$ to be
	\begin{align}\label{defnrab}
		\left\lVert[\Sigma]\right\rVert^R_\delta=\inf_{\substack{T\in\mathcal{F}_\delta(\mathbb{R}^{d+c},R)\\ T\in[\Sigma]^R}}\mathbf{M}_\delta^R(T).
	\end{align}
	We say an $R$-flat chain $T\in[\Sigma]^R$ is $R$-area-minimizing in $[\Sigma]^R$ with respect to metric $g,$ if $T$ achieves the $R$-area of $[\Sigma]^R$ defined in (\ref{defnra}), i.e.,
	\begin{align*}
		\mathbf{M}^R_\delta(T)=\left\lVert[\Sigma]\right\rVert^R_\delta.
	\end{align*}

\label{fctncmpb}The following inequality always holds
\begin{align}\label{eqinnorm}
	\left\lVert[\Sigma]\right\rVert^R_g\le \left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_g.
\end{align}

\label{defnpf}
	For a subset $S\subset H_d(\mathbb{R}^{d+c},W,\mathbb{Z}),$		define the set of $R$-area-minimizing representatives $\mathbf{MIN}_\delta^R\left(S\right)$ of $S^R$ to be
	\begin{align*}
		\mathbf{MIN}_\delta^R\left(S\right)=\{T|T\in \mathcal{F}_\delta(\mathbb{R}^{d+c},R),[T]\in S^R,\mathbf{M}^R_\delta(T)=\inf_{[\Gamma]\in S^R}\left\lVert[\Gamma]\right\rVert^R_\delta\}.
	\end{align*}

\label{thmvb}
	For all $[\Sigma]\in H_d(\mathbb{R}^{d+c},W,\mathbb{Z})$, there exists a positive integer $N_{[\Sigma],\delta}$, depending only on $[\Sigma]$, such that for all $n\ge N_{[\Sigma],\delta},$
	\begin{itemize}
		\item we have $			\left\lVert[\Sigma]\right\rVert_\delta^{\mathbb{Z}/n\mathbb{Z}}=\left\lVert[\Sigma]\right\rVert_\delta^\mathbb{Z},$
		\item the $\mathbb{Z}/n\mathbb{Z}$-reduction restricted to $\mathbf{MIN}_\delta^{\mathbb{Z}}\left([\Sigma]\right)$ is a one to one map from  		$\mathbf{MIN}_h^{\mathbb{Z}}\left([\Sigma]\right)$ to $\mathbf{MIN}_\delta^{\mathbb{Z}/n\mathbb{Z}}\left([\Sigma]\right)$.	
	\end{itemize}

Define
		\begin{align}\label{defncrsp}
			[\Sigma]\times[\Sigma']=\mathfrak{i}\left([\Sigma]\otimes [\Sigma']\right).
		\end{align}

The following inequality holds,
		\begin{align}\label{ineqprod}
			\left\lVert[\Sigma]\right\rVert^R_{g}\times \left\lVert[\Sigma']\right\rVert^R_{g'}\ge 
			\left\lVert[\Sigma]\times [\Sigma']\right\rVert^R_{g\times g'}.
		\end{align}

\label{fctfedco}
		When both $[\Sigma],[\Sigma']$ are of codimension $1$ and both $M,M'$ are orientable,
		\begin{align}\label{eqprodz}
			\left\lVert[\Sigma]\right\rVert^{\mathbb{Z}}_{g}\times \left\lVert[\Sigma']\right\rVert^{\mathbb{Z}}_{g'}=		\left\lVert[\Sigma]\times [\Sigma']\right\rVert^{\mathbb{Z}}_{g\times g'}.
		\end{align}

\label{thmkun}
		If $d\ge 1,c\ge 2$, $[\Sigma]$ is a non-torsion class on an orientable $M$, then for any real number $\kappa>1,$ any metric $g'$ on $M'$, there exists a non-empty open set $\Omega_{[\Sigma],g',\kappa}$ in the space of Riemannian metrics on $M$, a non-empty open set $\Omega_{[\Sigma],g',\kappa}'
i g'$ in the space of Riemannian metrics on $M'$, and  an integer $
