		\end{align}

\label{defntmb}
	Use $G_d(M,W,\mathbb{Z})$ to denote the torsion subgroup of $H_d(M,W,\mathbb{Z})$, i.e., 
	\begin{align*}
		G_d(M,W,\mathbb{Z})=\bigoplus_{i\in I}\mathbb{Z}/p_i^{\nu_i}\mathbb{Z}.
	\end{align*}Define the $d$-th torsion number $\tau_d$ of $(M,W)$ to be
	\begin{align*}
		\tau_d=\operatorname{lcm}_{i\in I}p_i^{\nu_i},
	\end{align*}where $\operatorname{lcm}$ means the 
	least common multiple. Set $\tau_d=1$ if $H_d(M,W,\mathbb{Z})$ is torsion-free.

\label{decompbs}
		Let $\{f_1,\cdots,f_{b_d},v_1,\cdots,v_{|I|}\}$ be a basis of $H_d(M,W,\mathbb{Z})$ so that 
		\begin{itemize}
			\item 	$\{f_1,\cdots,f_{b_d}\}$ is a $\mathbb{Z}$-linear independent basis of the factor $\mathbb{Z}^{b_d}$ in (\ref{decomph}),
			\item for all $j\in I,$ the element $v_j$ generates the $\mathbb{Z}/p_j^{\nu_j}\mathbb{Z}$ factor in (\ref{decomph}).
		\end{itemize}

\label{lemnt}
		If $X,Y\in H_d(M,W,\mathbb{Z})$ are two integral homology classes with the same $\mathbb{Z}/n\mathbb{Z}$-reduction, i.e., $X^{\mathbb{Z}/n\mathbb{Z}}=Y^{\mathbb{Z}/n\mathbb{Z}}$, then
		\begin{align*}
			X-Y\in nH_d(M,W,\mathbb{Z}).		\end{align*} Furthermore, when $\tau_d|n$, then $X-Y$ is $n$ times a non-torsion class.

It suffices to determine the kernel of $\mathbb{Z}/n\mathbb{Z}$-reduction. By \cite[Section 3.2 p. 215 property (5)]{AH}, the kernel of $\otimes \mathbb{Z}/n\mathbb{Z}$ of an abelian group is $n$ times the group. Thus, if $X,Y$ has the same $\mathbb{Z}/n\mathbb{Z}$-reduction, we have
		\begin{align*}
			X-Y\in nH_d(M,W,\mathbb{Z}).
		\end{align*}
		If $\tau_d|n,$ then $nH_d(M,W,\mathbb{Z})$ contains no nonzero element of the torsion subgroup $G_d(M,W,\mathbb{Z}).$ We are done.

\label{fctvols}
	We have
	\begin{align*}
		\mathcal{H}^{d-1}(\mathbf{S}^{d-1})=&d\frac{\Gamma\left(\frac{1}{2}\right)^d}{\Gamma\left(\frac{d}{2}+1\right)},\\
		\mathcal{H}^{d}(\mathbf{B}^{d-1})=&\frac{\Gamma\left(\frac{1}{2}\right)^d}{\Gamma\left(\frac{d}{2}+1\right)}.
	\end{align*}

\label{fctcf}
		Every $d$-dimensional $\mathbb{Z}$-rectifiable current $T$ 	belongs in the dual space of smooth differential forms, with actions on a form $\phi$ defined by
		\begin{align*}
			T(\phi)=\int_{\operatorname{Rect} T}\theta_T\phi(\eta)d\mathcal{H}^d,
		\end{align*}where $\operatorname{Rect} T$ is the Hausdorff $d$-dimensional (countably) underlying rectifiable set of $T$ defined in \cite[Section 4.1.28(4)]{HF}, $\theta_T$ is the density of the mass measure of $T$ and $\eta$ is the simple unit $d$-vector representing the oriented tangent space to $\operatorname{Rect} T$ Hausdorff $d$-dimensional a.e.~

\label{fctfce}In general,
		Federer's ``representative" modulo $n$
		\begin{itemize}
			\item  is not unique and many times there are infinitely many,  
			\item of a $\mathbb{Z}/n\mathbb{Z}$-cycle may not even be a $\mathbb{Z}$-cycle at all. 
		\end{itemize}

\label{defnsm}
	We say an $R$-rectifiable current $T$ is smooth at a point $p$ in the support of $T$ if there exists an open set $U$ containing $p$ on $M$, such that  $T$ restricted to $U$ equals $\alpha$ times a smooth submanifold $N$, with $\alpha\in R.$ The definitions of regular sets and singular sets of $T$ are as follows:
	\begin{itemize}
		\item The singular set of $T,$ $\operatorname{Sing} T,$ is defined as set of points in the support of $T$ where $T$ is not smooth,		
		\item 
		The regular set of $T,$ $\operatorname{Reg}T$, is defined as the set of points in the support of $T$ where $T$ is smooth. 
	\end{itemize}

We define the Almgren stratification of any subset $S$ of $\operatorname{Supp} T$ by setting 
	\begin{align*}
		\mathcal{S}_jS=\mathcal{S}_jT\cap S.
	\end{align*}

\label{lemdv}
		Suppose $T$ is a $d$-dimensional $\mathbb{Z}/n\mathbb{Z}$-flat chain on a not necessarily compact $(d+c)$-dimensional Riemannian manifold $M^{d+c}$. Let $S$ be a rectifiable current that is a Federer's ``representative" modulo $n$ of $T$. 
		Then
		\begin{align*}
			\operatorname{Supp}\partial S\subset \left(\operatorname{Reg}(T)\cap\left\{p\bigg|\theta_T(p)<\frac{n}{2}\right\}\right)^\complement,
		\end{align*}where $\operatorname{Reg}(T)$ denotes the regular part of $T.$

\label{fctdstin}
			The inequality		\begin{align}\label{eqtatr}
				|\theta_T(p)\pm n\theta_R(x)|\ge \frac{n}{2},
			\end{align}holds
			where equality is achieved if and only if $\theta_T(p)=\frac{n}{2},\theta_R(x)=1.$

\label{defnrareaall}
	For any $R$-homology class $\omega\in H_d(M,R),$ define	\begin{align}\label{defnrall}
		\left\lVert\omega\right\rVert^R_g=\inf_{\substack{T\in\mathcal{F}_g(M,R)\\ T\in\omega}}\mathbf{M}_g^R(T).
	\end{align}
For any subset $W$ of $H_d(M,R)$, define the set of $R$-area-minimizing representatives $\mathbf{MIN}_g^R(W)$ of $W$ to be
	\begin{align*}
		\mathbf{MIN}_g^R\left(W\right)=\left\{T\bigg|T\in \mathcal{F}_g(M,R),[T]\in W,\mathbf{M}^R_g(T)=\inf_{\omega\in W}\left\lVert\omega\right\rVert^R_g\right\}.
	\end{align*}

For any integer $k\in \mathbb{Z}$, $\omega\in H_d(M,R),$ we have
	\begin{align}\label{inns}
		\left\lVertk\omega\right\rVert_g^R\le |k|\left\lVert\omega\right\rVert_g^R.
	\end{align}

\label{fctnrt}We have
	\begin{itemize}
		\item $\left\lVert\cdot\right\rVert^{\mathbb{R}}_g$ is turns the the vector space $H_d(M,\mathbb{R})$ into a finite dimensional Banach space, 
		\item		$\left\lVert[\Sigma]\right\rVert^{\mathbb{R}}_g\not=0$  if and only if $[\Sigma]$ is a non-torsion class.
		\item we have
		\begin{align}\label{eqfed}
			\lim_{\substack{k\to\infty\\ k\in\mathbb{N}}}\frac{\left\lVertk[\Sigma]\right\rVert_g^{\mathbb{Z}}}{k}=\left\lVert[\Sigma]\right\rVert_g^{\mathbb{R}}.
		\end{align}
	\end{itemize}

\label{fctfc}
	For any torsion class $\tau\in H_d(M,\mathbb{Z})$, we have
	\begin{align*}
		\left\lVert\tau+[\Sigma]\right\rVert^{\mathbb{R}}_g=\left\lVert[\Sigma]\right\rVert^{\mathbb{R}}_g.
	\end{align*}

\label{lemhn}
	If an integer $k\in \left(-\frac{n}{2},\frac{n}{2}\right]$ invertible in $\mathbb{Z}/n\mathbb{Z}$ with its unique inverse in 	$\left(-\frac{n}{2},\frac{n}{2}\right]$ denoted by $l,$ then for any $\omega\in H_d(M,\mathbb{Z}/n\mathbb{Z}),$ we have
	\begin{align*}
		|l|^{-1} \left\lVert\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}}\le\left\lVertk\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}}\le |k|\left\lVert\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}},
	\end{align*}
	and thus
	\begin{align}\label{inhn}
		\frac{2}{n}\left\lVert\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}}\le\left\lVertk\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}}\le \frac{n}{2}\left\lVert\omega\right\rVert_g^{\mathbb{Z}/n\mathbb{Z}}.
	\end{align}

\label{lemnorm}
	Fix a basis $\{v_1,\cdots,v_b\}$ of $\mathbb{R}^b$. For any continuous Banach norm $\left\lVert\cdot\right\rVert$ on $\mathbb{R}^n,$ there exists a $C>0$ that depends continuously on $\left\lVert\cdot\right\rVert,$ so that 
	\begin{align*}
		\sum_{j=1}^b|a_j|\left\lVertv_j\right\rVert\le C \left\lVert\sum_{j=1}^b a_jv_j\right\rVert,
	\end{align*}with each $a_j\in \mathbb{R}.$

For $v=\sum_{j=1}^b a_jv_j$ with each $a_j\in\mathbb{R}$ define
	\begin{align*}
		\left\lVertv\right\rVert^\infty=\sum_{j=1}^b|a_j|\left\lVertv_j\right\rVert.
	\end{align*}
	It is straightforward to verify that $\left\lVert\cdot\right\rVert^\infty$ is a continuous function Banach norm on $\mathbb{R}^n$. We need to prove that $\frac{\left\lVert\cdot\right\rVert^\infty}{\left\lVert\cdot\right\rVert}$ is bounded. By homogeneity, it suffices to verify this on the norm unit sphere $\{v\in \mathbb{R}^n|\left\lVertv\right\rVert=1\}.$ This follows from continuity of $\left\lVert\cdot\right\rVert^\infty,$ and the the compactness of norm unit sphere.

\label{lemmsbd}
	There exists a continuous function $\upsilon$ mapping the space of Riemannian metrics	to $\mathbb{R}_{\ge 0},$ such that  \begin{align*}
		\sup_{[\Sigma]\in H_d(M,\mathbb{Z})\textnormal{ is free}}		\frac{\left\lVert[\Sigma]\right\rVert_g^{\mathbb{Z}}}{\left\lVert[\Sigma]\right\rVert_g^{\mathbb{R}}}\le \upsilon(g).
	\end{align*}

Recall Assumption \ref{decompbs}. Every non-torsion class $[\Sigma]\in H_d(M,\mathbb{Z})$ can be written as 
	\begin{align*}
		[\Sigma]=\sum_{j=1}^{b_d}\alpha_jf_j+\sum_{i\in I}\beta_iv_i,
	\end{align*}
	with each $\alpha_j\in \mathbb{Z},\beta_i\in\mathbb{Z}\cap[0,p_j^{\nu_j}],$ and not all $a_i$ are $0.$ By Lemma \ref{lemnorm} there is a continuous function $C$ from the space of Riemannian metrics to $\mathbb{R}_{> 0}$ so that
	\begin{align*}
		\left\lVert[\Sigma]\right\rVert^{\mathbb{R}}_g=\left\lVert\sum_{j=1}^{b_d}\alpha_jf_j\right\rVert^{\mathbb{R}}_g\ge C^{-1} \sum_{j=1}^{b_d}|\alpha_j|\left\lVertf_j\right\rVert^{\mathbb{R}}_g,
	\end{align*}where at the first equality we have used Fact \ref{fctfc}.
	By the mediant inequality and $\max_j|\alpha_j|\ge 1$, we have
	\begin{align*}
		\frac{\left\lVert[\Sigma]\right\rVert_g^{\mathbb{Z}}}{\left\lVert[\Sigma]\right\rVert_g^{\mathbb{R}}}\le& C\frac{\sum_{j=1}^{b_d} |\alpha_j|\left\lVertf_j\right\rVert_g^{\mathbb{Z}}+\sum_{i\in I}|\beta_i|\left\lVertv_i\right\rVert^{\mathbb{Z}}_g}{\sum_{j=1}^{b_d}|\alpha_j|\left\lVertf_j\right\rVert^{\mathbb{R}}_g}\\
		=&C\frac{\sum_{j=1}^{b_d} |\alpha_j|\left\lVertf_j\right\rVert_g^{\mathbb{Z}}}{\sum_{j=1}^{b_d}|\alpha_j|\left\lVertf_j\right\rVert^{\mathbb{R}}_g}+C\frac{
			\sum_{i\in I}|\beta_i|\left\lVertv_i\right\rVert^{\mathbb{Z}}_g}{\sum_{j=1}^{b_d}|\alpha_j|\left\lVertf_j\right\rVert^{\mathbb{R}}_g}\\
		\le&C\max_{1\le j\le b_d} \frac{\left\lVertf_j\right\rVert^{\mathbb{Z}}_g}{\left\lVertf_j\right\rVert_g^{\mathbb{R}}}+C\tau_b\frac{\max_{i\in I}\left\lVertv_i\right\rVert^{\mathbb{Z}}_g}{\min_{1\le j\le b_d}\left\lVertf_j\right\rVert_g^{\mathbb{R}}}.
	\end{align*}By Fact \ref{fctnr}, we are done.

\label{defncal}(Definition of calibrations)
		\begin{itemize}
			\item 	We say a closed $d$-dimensional Hausdorff measurable $d$-form $\phi$ on a (possibly open) ambient manifold is a calibration if its comass is at most $1.$ 
			\item 
			We say a $d$-dimensional integral current $T$ is calibrated by $\phi,$ if $d$-dimensional Hausdorff measure a.e.~where $\phi$ restricted to the tangent space of $T$ equals the volume form of $T.$
		\end{itemize}

\label{defncalr}
		We say an $\mathbb{R}$-flat cochain $\alpha,$ is a calibration on $(M,g),$ if 
		\begin{itemize}
			\item $d\alpha=0,$
			\item $\alpha(T)\le \mathbf{M}^{\mathbb{R}}_g(T),$ for all $\mathbb{R}$-flat chains $T.$
		\end{itemize}
		We say an $\mathbb{R}$-flat chain $T$ is calibrated by $\alpha,$ if
		$$\alpha(T)=\mathbf{M}^{\mathbb{R}}_g(T).$$

\label{fctsub}
