		\int_{\pi_p(W)\cap g.S^c}\theta_{\pi_p\left( B^R\right)}(q)d\mathcal{H}^0(q)\le\left|[\Sigma]^R\right|\int_{\pi_p(W)\cap g.S^c}|\pi_p^{-1}(q)\cap W^+|d\mathcal{H}^0(q).	
	\end{equation}
	Let $P(g.S^c)$ denote the unique affine $(c+1)$-dimensional plane passing through $p$ and $g.S^c.$ We have
	\begin{align*}
		\pi_p(P(g.S^c)\cap W)=\pi_p(P(g.S^c))\cap \pi_p(W)=\pi_p(W)\cap g.S^c.
	\end{align*}
	This implies that
	\begin{align}\label{eqcnb}
		\int_{\pi_p(W)\cap g.S^c}
		|\pi_p^{-1}(q)\cap W^+|d\mathcal{H}^0(q)=\#|	P(g.S^c)\cap W^+|
	\end{align}
	Bringing (\ref{eqcnb}) into (\ref{eqpti}), we deduce that 
	\begin{align}\label{eqdsf}
		\int_{\pi_p(W)\cap g.S^c}\theta_{\pi_p\left( B^R\right)}(q)d\mathcal{H}^0(q)\le\left|[\Sigma]^R\right|\#|	P(g.S^c)\cap W^+|
	\end{align}		
	Apply Lemma \ref{fctsub} by translating $p$ to the origin, we deduce that for Haar almost every $g\in O(d+c)$, we have
	\begin{align}\label{eqsubf}
		\#|	P(g.S^c)\cap W^+|\le\#|	g.P(S^c)\cap W|\le \mu_W.
	\end{align}
	Combining (\ref{eqsubf}) (\ref{eqdsf}) and (\ref{eqmst}), we deduce (\ref{eqmsr2}).

\label{fctsubts}
	For any point $p\in \mathbb{R}^{d+c}$, we have 
	\begin{align*}
		\theta_T(p)	\le\frac{1}{2}\mu_W\left|B^R\right|.
	\end{align*}
	When we are in the second case of Assumption \ref{assumpmb}, for any $T\in\mathbf{MIN}^R_\delta([\Sigma]^R)$ we have
	\begin{align*}
		\theta_T(p)	\le\frac{1}{2}\mu_W\left|[\Sigma]^R\right|.
	\end{align*}

\label{fctplane}
	For $p\in \mathbb{R}^{d+c},$ and $T\in\mathbf{MIN}^R_\delta([\Sigma_{P,Q}])$ we have
	\begin{align*}
		\theta_T(p)\le 2
	\end{align*}and strict inequality holds for $p\not=0.$

By definition, we have $$\left|[\Sigma_{P,Q}]^R\right|=1.$$ Recall Fact \ref{fctsub} with $p$ translated to the origin. If an affine $(c+1)$-dimensional plane $V$ intersects $W_{P,Q}$ at finitely many points, then the cardinality $\#|V\cap W_{P,Q}|$ is at most $4$, i.e., $V$ intersecting $P,Q$ both at a line. Thus, we have $$\mu_{W_{P,Q}}=4.$$
	
	By Fact \ref{fctsubts}, we deduce that	\begin{align}\label{eqtt2}
		\theta_T(p)\le 2.\end{align} 
	
	To prove that strict inequality holds in (\ref{eqtt2}) for $p\not=0$, we prove the contrapositive.
	
	In other words, we will prove that equality in (\ref{eqtt2}) implies $p=0$.
	
	We need to recall the proof of Fact \ref{fctsubts}. Recall equality (\ref{eqmst}) Equality in (\ref{eqtt2}) holds implies that for Haar a.e.~ $g\in O(d+c)$, we have
	\begin{align}
		\label{eqdstp}	\int_{\pi_p(W_P)\cap g.S^c}\theta_{\pi_p\left(\partial \Sigma^R_{P,Q}\right)}d\mathcal{H}^0=2,\\
		\label{eqdstq}	\int_{\pi_p(W_Q)\cap g.S^c}\theta_{\pi_p\left(\partial \Sigma^R_{P,Q}\right)}d\mathcal{H}^0=2.
	\end{align}
	If $p\not\in P$, then take a flat coordinate system $(x_1,\cdots,x_{d+c})$ so that $P$ is spanned by $x_1,\cdots,x_d$-axes vectors and $p=(p_1,\cdots,p_{d+c})$ with $p_{d+c}>0.$ Consider the affine $(c+1)$-dimensional plane $P'_p$ parameterized by
	\begin{align*}
		P'_p=\{(p_1+x_1,\cdots,p_{c+1}+x_{c+1},p_{c+2},\cdots,x_{d+c})|(x_d,\cdots,p_{d+c})\in\mathbb{R}^{c+1}\}.
	\end{align*}
	Then $P'_p\cap P=\emptyset.$ Thus, \begin{align*}
		\pi_p(P'_p)\cap \pi_p(W_P)=\emptyset
	\end{align*} and there exists an open set $U(\pi_p(P'_p))$ containing $\pi_p(P'_p)$ so that
	\begin{align*}
		U(\pi_p(P'_p))\cap \pi_p(W_P)=\emptyset.
	\end{align*}  However, $\pi_p(P'_p)$ is a totally geodesic $c$-dimensional sphere in $\mathbf{S}_1(p)$, so there exists $g_P$ so that  $g_P(S^c)=\pi_p(P'_p).$ For a neighborhood $U(g_P)$ of $g_P$ in $O(d+c)$ we have $h(\pi_p(P'_p))\subset 	U(\pi_p(P'_p)).$ In other words, for $h\in U(g_P)$, we have $\pi_P(W_P)\cap h(S^c)=\emptyset.$ 
	
	Thus, if (\ref{eqdstp}) holds for Haar a.e.~ $g\in O(d+c)$,  we must have $p\in V.$ The same argument works for $Q$ and we deduce that if (\ref{eqdstq}) holds then $p\in Q.$ We are done.

\label{assumpmc}
Consider the quadruples of configures $(M^{d+c},W,g,\Omega_g)$ with $d,c\in\mathbb{Z}_{\ge 1}$. Assume that one of the followings holds
